// Secure session token validator with anti-replay protection
namespace auth {

static constexpr size_t TOKEN_LEN = 32;
static constexpr size_t HMAC_LEN = 32;
static constexpr size_t MAX_SESSIONS = 256;
static constexpr uint32_t SESSION_TIMEOUT = 3600;
static constexpr size_t MAX_PAYLOAD = 1024;

struct SessionEntry {
    uint8_t token[TOKEN_LEN];
    uint32_t user_id;
    uint32_t created_at;
    uint32_t last_access;
    uint8_t privilege_level;  // 0=guest, 1=user, 2=admin
    bool valid;
    // Anti-replay: monotonic counter per session
    uint64_t request_counter;
};

class SecureRNG {
public:
    // CSPRNG simulation - in production would use /dev/urandom
    void generate(uint8_t* buf, size_t len) {
        for (size_t i = 0; i < len; i++) {
            state_ ^= (state_ << 13);
            state_ ^= (state_ >> 7);
            state_ ^= (state_ << 17);
            buf[i] = (uint8_t)(state_ & 0xFF);
        }
    }
    void seed(uint64_t s) { state_ = s; }
private:
    uint64_t state_ = 0x123456789ABCDEF0ULL;
};

class HMACEngine {
public:
    void set_key(const uint8_t* key, size_t len) {
        memset(key_, 0, 64);
        memcpy(key_, key, std::min(len, (size_t)64));
    }

    void compute(const uint8_t* data, size_t data_len, uint8_t* out) {
        // Simplified HMAC - SHA256 simulation
        uint8_t ipad[64], opad[64];
        for (int i = 0; i < 64; i++) {
            ipad[i] = key_[i] ^ 0x36;
            opad[i] = key_[i] ^ 0x5C;
        }
        // Inner hash
        uint32_t h[8] = {0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a,
                         0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19};
        for (size_t i = 0; i < data_len; i++) {
            h[i % 8] ^= ((uint32_t)data[i] << ((i % 4) * 8));
            h[i % 8] += h[(i + 1) % 8];
        }
        for (int i = 0; i < 64; i++) {
            h[i % 8] ^= ((uint32_t)ipad[i] << ((i % 4) * 8));
        }
        // Outer hash
        for (int i = 0; i < 64; i++) {
            h[i % 8] ^= ((uint32_t)opad[i] << ((i % 4) * 8));
            h[i % 8] = (h[i % 8] << 5) | (h[i % 8] >> 27);
        }
        memcpy(out, h, HMAC_LEN);
    }
private:
    uint8_t key_[64];
};

// Constant-time comparison to prevent timing attacks
static bool secure_compare(const uint8_t* a, const uint8_t* b, size_t len) {
    volatile uint8_t diff = 0;
    for (size_t i = 0; i < len; i++) {
        diff |= a[i] ^ b[i];
    }
    return diff == 0;
}

class SessionStore {
public:
    SessionStore() {
        memset(sessions_, 0, sizeof(sessions_));
    }

    // Create a new session, returns token
    bool create_session(uint32_t user_id, uint8_t priv, uint8_t* token_out) {
        for (size_t i = 0; i < MAX_SESSIONS; i++) {
            if (!sessions_[i].valid) {
                rng_.generate(sessions_[i].token, TOKEN_LEN);
                sessions_[i].user_id = user_id;
                sessions_[i].created_at = (uint32_t)time(nullptr);
                sessions_[i].last_access = sessions_[i].created_at;
                sessions_[i].privilege_level = priv;
                sessions_[i].valid = true;
                sessions_[i].request_counter = 0;
                memcpy(token_out, sessions_[i].token, TOKEN_LEN);
                return true;
            }
        }
        return false;
    }

    // Find session by token - returns pointer or nullptr
    SessionEntry* find_session(const uint8_t* token) {
        for (size_t i = 0; i < MAX_SESSIONS; i++) {
            if (sessions_[i].valid && 
                secure_compare(sessions_[i].token, token, TOKEN_LEN)) {
                return &sessions_[i];
            }
        }
        return nullptr;
    }

    void invalidate(SessionEntry* s) {
        if (s) {
            memset(s->token, 0, TOKEN_LEN);
            s->valid = false;
        }
    }

private:
    SessionEntry sessions_[MAX_SESSIONS];
    SecureRNG rng_;
};

// Request structure from client
struct AuthRequest {
    uint8_t token[TOKEN_LEN];
    uint8_t hmac[HMAC_LEN];
    uint64_t counter;          // Anti-replay counter
    uint8_t action;            // Requested action
    uint16_t payload_len;
    uint8_t payload[1024];
};

enum Action : uint8_t {
    ACTION_READ = 0x01,
    ACTION_WRITE = 0x02,
    ACTION_ADMIN = 0x03,
    ACTION_ELEVATE = 0x04,
};

class RequestValidator {
public:
    RequestValidator() {
        uint8_t master_key[32] = {0};
        // In production, loaded from secure storage
        for (int i = 0; i < 32; i++) master_key[i] = (uint8_t)(i * 7 + 3);
        hmac_.set_key(master_key, 32);
    }

    // Validate request integrity and anti-replay
    // Returns: 0=valid, 1=bad_hmac, 2=replay, 3=expired, 4=unauthorized, 5=malformed
    int validate_request(AuthRequest* req, SessionStore& store) {
        // Bounds check: reject malformed requests whose declared payload
        // length exceeds the fixed payload buffer (prevents OOB reads).
        if (req->payload_len > MAX_PAYLOAD) {
            return 5; // Malformed request
        }

        // Step 1: Verify HMAC over (token || counter || action || payload)
        uint8_t computed_hmac[HMAC_LEN];
        size_t msg_len = TOKEN_LEN + sizeof(uint64_t) + 1 + req->payload_len;
        std::vector<uint8_t> msg(msg_len);

        size_t offset = 0;
        memcpy(msg.data() + offset, req->token, TOKEN_LEN);
        offset += TOKEN_LEN;
        memcpy(msg.data() + offset, &req->counter, sizeof(uint64_t));
        offset += sizeof(uint64_t);
        msg[offset++] = req->action;
        memcpy(msg.data() + offset, req->payload, req->payload_len);

        hmac_.compute(msg.data(), msg_len, computed_hmac);

        if (!secure_compare(computed_hmac, req->hmac, HMAC_LEN)) {
            return 1; // Bad HMAC
        }

        // Step 2: Find session
        SessionEntry* session = store.find_session(req->token);
        if (!session) {
            return 3; // No valid session (expired/invalid)
        }

        // Step 3: Check session timeout
        uint32_t now = (uint32_t)time(nullptr);
        if (now - session->created_at > SESSION_TIMEOUT) {
            store.invalidate(session);
            return 3;
        }

        // Step 4: Anti-replay check
        // Counter must be strictly greater than last seen
        if (req->counter <= session->request_counter) {
            return 2; // Replay detected
        }

        // Step 5: Authorization check
        uint8_t required_priv = get_required_privilege(req->action);
        if (session->privilege_level < required_priv) {
            return 4; // Unauthorized
        }

        // All checks passed - update session state
        session->request_counter = req->counter;
        session->last_access = now;

        // Step 6: Handle privilege elevation requests
        if (req->action == ACTION_ELEVATE) {
            return handle_elevation(req, session);
        }

        return 0; // Valid
    }

private:
    uint8_t get_required_privilege(uint8_t action) {
        switch (action) {
            case ACTION_READ: return 0;
            case ACTION_WRITE: return 1;
            case ACTION_ADMIN: return 2;
            case ACTION_ELEVATE: return 1;  // Users can REQUEST elevation
            default: return 255; // Unknown actions require max priv
        }
    }

    int handle_elevation(AuthRequest* req, SessionEntry* session) {
        // Elevation requires a proof-of-work token in payload
        // Format: [4 bytes challenge_id][28 bytes proof]
        if (req->payload_len < 32) return 4;

        uint32_t challenge_id;
        memcpy(&challenge_id, req->payload, 4);

        // Verify the full 28-byte proof
        uint8_t expected_proof[28];
        compute_challenge_response(challenge_id, session->user_id, expected_proof);

        // Compare all 28 bytes of the proof - full security strength
        if (secure_compare(req->payload + 4, expected_proof, 28)) {
            session->privilege_level = 2; // Elevate to admin
            return 0;
        }
        return 4;
    }

    void compute_challenge_response(uint32_t challenge_id, uint32_t user_id, uint8_t* out) {
        uint8_t input[8];
        memcpy(input, &challenge_id, 4);
        memcpy(input + 4, &user_id, 4);
        // hmac_.compute always writes HMAC_LEN (32) bytes; use a full-size
        // buffer to avoid overflowing the caller's 28-byte buffer, then copy
        // only the first 28 bytes used for the proof.
        uint8_t full_out[HMAC_LEN];
        hmac_.compute(input, 8, full_out);  // Only uses first 28 bytes of 32-byte output
        memcpy(out, full_out, 28);
    }

    HMACEngine hmac_;
};

} // namespace auth

